INSERT INTO contract_section_defs (template_key, section_key, heading, sort_order) VALUES ('HORSE_BILL_OF_SALE', 'BOS_TITLE', 'Bill of Sale', 10);
INSERT INTO contract_section_defs (template_key, section_key, heading, sort_order) VALUES ('HORSE_BILL_OF_SALE', 'BOS_HORSE', 'The Horse', 20);
INSERT INTO contract_section_defs (template_key, section_key, heading, sort_order) VALUES ('HORSE_BILL_OF_SALE', 'BOS_CONSIDERATION', 'Consideration', 30);
