-- ═══ HORSE_BILL_OF_SALE: clauses (bodies verbatim from the content file) ═══
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_TITLE', 'BOS_TITLE.INTRO', NULL, $BODY$EQUINE BILL OF SALE. This Bill of Sale is made effective as of {{DOC.EFFECTIVE_DATE}} by {{SELLER.FULL_NAME}} of {{SELLER.ADDRESS}} ("Seller") in favor of {{BUYER.FULL_NAME}} of {{BUYER.ADDRESS}} ("Buyer").$BODY$, 'input', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_TITLE', 'BOS_TITLE.CO_BUYER', NULL, $BODY${{COBUYER.FULL_NAME}} of {{COBUYER.ADDRESS}} ("Co-Buyer") takes title jointly with Buyer as follows: {{TXN.CO_BUYER_TITLE_FORM}}. Every reference to Buyer in this Bill of Sale includes Co-Buyer.$BODY$, 'input', 20, '{"equals":["YES"],"field_key":"TXN.CO_BUYER_ENABLED"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_HORSE', 'BOS_HORSE.IDENTITY', NULL, $BODY$This Bill of Sale conveys the following horse (the "Horse"): {{HORSE.REGISTERED_NAME}}
Barn Name: {{HORSE.BARN_NAME}}
Color: {{HORSE.COLOR}}
Markings: {{HORSE.MARKINGS}}
Breed: {{HORSE.BREED}}
Registration Number: {{HORSE.REGISTRATION_NUMBER}}
Sex: {{HORSE.SEX}}
Foaling date: {{HORSE.AGE_DOB}}
Height: {{HORSE.HEIGHT}}
Microchip: {{HORSE.MICROCHIP}}
Passport: {{HORSE.PASSPORT_NUMBER}}$BODY$, 'input', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_CONSIDERATION', 'BOS_CONSIDERATION.PRICE', NULL, $BODY$The purchase price for the Horse is {{TXN.PURCHASE_PRICE}} (the "Purchase Price"), the receipt and sufficiency of which are acknowledged to the extent stated below. The parties state this Purchase Price for all purposes, including California Business and Professions Code Section 19525 where applicable.$BODY$, 'input', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.PAID', NULL, $BODY$Seller acknowledges receipt of the Purchase Price in full and hereby sells, transfers, conveys, and delivers to Buyer all of Seller's right, title, and interest in and to the Horse, together with the Horse's registration papers and passport where applicable, TO HAVE AND TO HOLD the same unto Buyer and Buyer's successors and assigns forever.$BODY$, 'prose', 10, '{"equals":["PAID_IN_FULL"],"field_key":"TXN.BOS_PAYMENT_STATUS"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.INSTALLMENT', NULL, $BODY$The Purchase Price is payable in installments under the parties' Horse Sale and Purchase Agreement. Seller hereby transfers possession of the Horse to Buyer, and title to the Horse passes to Buyer only upon Seller's receipt of the Purchase Price in full as provided in that Agreement, until which time Seller retains title and a purchase-money security interest in the Horse as stated in that Agreement. Upon payment in full, this Bill of Sale operates without further action to convey all of Seller's right, title, and interest in and to the Horse to Buyer.$BODY$, 'prose', 20, '{"equals":["INSTALLMENTS"],"field_key":"TXN.BOS_PAYMENT_STATUS"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_CONVEYANCE', 'BOS_CONVEYANCE.PENDING', NULL, $BODY$[Pending — select whether the Purchase Price is paid in full or payable in installments. This placeholder is replaced by the applicable conveyance language and blocks signing.]$BODY$, 'prose', 30, '{"equals":[""],"field_key":"TXN.BOS_PAYMENT_STATUS"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.TITLE', NULL, $BODY$Seller warrants that Seller is the lawful owner of the Horse, has full right and authority to sell and convey the Horse, and that the Horse is free and clear of all liens, security interests, and encumbrances except as disclosed in writing to Buyer, and Seller will defend title to the Horse against the lawful claims of all persons.$BODY$, 'prose', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.CONDITION_XREF', NULL, $BODY$The Horse is conveyed subject to, and with the benefit of, the representations, disclosures, disclaimers of warranty, releases, and other terms of the parties' Horse Sale and Purchase Agreement of even or prior date, which remains in full force. In the event of a conflict between this Bill of Sale and that Agreement, that Agreement controls.$BODY$, 'prose', 20, '{"equals":["YES"],"field_key":"TXN.BOS_HAS_SALE_AGREEMENT"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.CONDITION_STANDALONE', NULL, $BODY$Except for the warranty of title above, the Horse is sold AS IS, and SELLER MAKES NO WARRANTIES, EXPRESS OR IMPLIED, REGARDING THE HORSE, INCLUDING THE WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE, and no warranty is made regarding the Horse's future soundness, health, temperament, performance, suitability for any discipline or rider, or value. This disclaimer does not limit claims arising from fraud. Buyer acknowledges the opportunity to have the Horse examined by a veterinarian of Buyer's choosing before purchase.$BODY$, 'prose', 30, '{"equals":["NO"],"field_key":"TXN.BOS_HAS_SALE_AGREEMENT"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_WARRANTY', 'BOS_WARRANTY.PENDING', NULL, $BODY$[Pending — state whether a Horse Sale and Purchase Agreement accompanies this Bill of Sale. This placeholder is replaced by the applicable condition language and blocks signing.]$BODY$, 'prose', 40, '{"equals":[""],"field_key":"TXN.BOS_HAS_SALE_AGREEMENT"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.DISCLOSURE', NULL, $BODY$The following person or entity acted as agent or intermediary in this transaction and receives compensation in connection with it: {{TXN.AGENT_NAME}}, acting on behalf of {{TXN.AGENT_ACTING_FOR}}, receiving compensation of {{TXN.AGENT_COMPENSATION}} paid by {{TXN.AGENT_PAID_BY}}. Where the agent acted on behalf of both Seller and Buyer, each party acknowledges that it received prior written disclosure of, and consented in writing to, the dual agency. The parties acknowledge that under California Business and Professions Code Section 19525, where it applies, an agent receiving compensation in excess of five hundred dollars in connection with the sale of a racing or showing equine must be authorized by a written agreement signed by the party the agent represents, and this Bill of Sale is delivered in satisfaction of the written bill of sale required by that statute.$BODY$, 'input', 10, '{"equals":["INCLUDED"],"field_key":"TXN.AGENT_ELECTION"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.NONE', NULL, $BODY$No agent or intermediary receives compensation in connection with this transaction.$BODY$, 'prose', 20, '{"equals":["NOT_INCLUDED"],"field_key":"TXN.AGENT_ELECTION"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_AGENT', 'BOS_AGENT.PENDING', NULL, $BODY$[Pending — state whether a compensated agent or intermediary participated in this transaction. This placeholder is replaced by the applicable statement and blocks signing.]$BODY$, 'prose', 30, '{"equals":[""],"field_key":"TXN.AGENT_ELECTION"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_GOVERNING', 'BOS_GOVERNING.CHOICE', NULL, $BODY$This Bill of Sale is governed by the laws of the State of California. Any dispute arising out of or relating to this Bill of Sale shall be resolved in the same manner as disputes under the parties' Horse Sale and Purchase Agreement where one exists, and otherwise by final and binding arbitration in San Diego County, California, before a single arbitrator administered by JAMS under its applicable rules, with the same small-claims and provisional-relief rights stated in that Agreement.$BODY$, 'prose', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.BLOCK', NULL, $BODY$IN WITNESS WHEREOF, Seller and Buyer execute this Bill of Sale as of the date first written above.

SELLER
Signature: {{SIG.SELLER.NAME}}
Printed Name: {{SELLER.PRINTED_NAME}}
Date: {{SIG.SELLER.DATE}}$BODY$, 'prose', 10, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.SELLER_CAPACITY', NULL, $BODY$By: {{SELLER.ENTITY_SIGNER_NAME}}
Title: {{SELLER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{SELLER.FULL_NAME}}$BODY$, 'input', 20, '{"equals":["ENTITY"],"field_key":"SELLER.PARTY_TYPE"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.BUYER_BLOCK', NULL, $BODY$BUYER
Signature: {{SIG.BUYER.NAME}}
Printed Name: {{BUYER.PRINTED_NAME}}
Date: {{SIG.BUYER.DATE}}$BODY$, 'prose', 30, NULL);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.BUYER_CAPACITY', NULL, $BODY$By: {{BUYER.ENTITY_SIGNER_NAME}}
Title: {{BUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{BUYER.FULL_NAME}}$BODY$, 'input', 40, '{"equals":["ENTITY"],"field_key":"BUYER.PARTY_TYPE"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.COBUYER_BLOCK', NULL, $BODY$CO-BUYER
Signature: {{SIG.COBUYER.NAME}}
Printed Name: {{COBUYER.PRINTED_NAME}}
Date: {{SIG.COBUYER.DATE}}$BODY$, 'input', 50, '{"equals":["YES"],"field_key":"TXN.CO_BUYER_ENABLED"}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.COBUYER_CAPACITY', NULL, $BODY$By: {{COBUYER.ENTITY_SIGNER_NAME}}
Title: {{COBUYER.ENTITY_SIGNER_TITLE}}
Signing on behalf of {{COBUYER.FULL_NAME}}$BODY$, 'input', 60, '{"all":[{"equals":["YES"],"field_key":"TXN.CO_BUYER_ENABLED"},{"equals":["ENTITY"],"field_key":"COBUYER.PARTY_TYPE"}]}'::jsonb);
INSERT INTO contract_clause_defs (template_key, section_key, clause_key, heading, body, clause_type, sort_order, conditional_on)
VALUES ('HORSE_BILL_OF_SALE', 'BOS_SIGNATURES', 'BOS_SIGNATURES.NOTARY', 'Notary Acknowledgment', $BODY$State of California, County of _______________. On _______________ before me, _______________, Notary Public, personally appeared _______________, who proved to me on the basis of satisfactory evidence to be the person(s) whose name(s) is/are subscribed to the within instrument and acknowledged to me that he/she/they executed the same in his/her/their authorized capacity(ies), and that by his/her/their signature(s) on the instrument the person(s), or the entity upon behalf of which the person(s) acted, executed the instrument. I certify under PENALTY OF PERJURY under the laws of the State of California that the foregoing paragraph is true and correct. WITNESS my hand and official seal.
Signature: _______________ (Seal)$BODY$, 'prose', 70, '{"equals":["INCLUDED"],"field_key":"TXN.NOTARY_ELECTION"}'::jsonb);

