-- HORSE_SALE_V2: HORSE identity defs derived from the live lease rows (owner → SELLER)
INSERT INTO contract_field_defs (template_key, field_key, label, section, clause_key, owner_role,
       value_type, input_kind, format_type, options, conditional_on, required, sort_order, guidance)
SELECT 'HORSE_SALE_V2', d.field_key, d.label, 'HORSE', 'HORSE.IDENTITY', 'SELLER',
       d.value_type, d.input_kind, d.format_type, d.options, NULL, d.required,
       5000 + (row_number() OVER (ORDER BY d.sort_order))::int * 10, d.guidance
  FROM contract_field_defs d
 WHERE d.template_key = 'HORSE_LEASE_V2'
   AND d.field_key IN ('HORSE.REGISTERED_NAME', 'HORSE.COLOR', 'HORSE.MARKINGS', 'HORSE.BREED', 'HORSE.REGISTRATION_NUMBER', 'HORSE.SEX', 'HORSE.AGE_DOB', 'HORSE.MICROCHIP', 'HORSE.PASSPORT_NUMBER', 'HORSE.CURRENT_LOCATION')
ON CONFLICT (template_key, field_key) DO NOTHING;

